On Desktop (Node-API), use the Lynx C/C++ APIs to register native capabilities
with the Lynx runtime. Native Module methods are exposed to `NativeModules`
through the Weak Node-API environment owned by the Lynx JavaScript runtime, and
the registration entry point is `LYNX_REGISTER_NATIVE_MODULE`.

The [`@lynx-js/weak-node-api`](https://www.npmjs.com/package/@lynx-js/weak-node-api)
npm package publishes the Weak Node-API headers, including `napi.h`,
`node_api.h`, `weak_napi_defines.h`, and `weak_napi_undefs.h`. Add it to your
native library project and include its `headers/` directory in the build so
your code can use the `Napi::` C++ wrapper types.

The example below matches the TypeScript declaration above and exports
`NativeLocalStorageModule`.

```cpp title="shared/nativeModule/NativeLocalStorageModule.cc"
#include <lynx/registration.h>

#include "napi.h"

#ifdef USE_WEAK_SUFFIX_NAPI
#include "weak_napi_defines.h"
#endif

#include <string>
#include <unordered_map>

namespace {

std::unordered_map<std::string, std::string> g_storage;

void Check(napi_env env, napi_status status) {
  if (status != napi_ok) {
    napi_throw_error(env, nullptr, "N-API call failed");
  }
}

void SetFunction(
    napi_env env,
    napi_value object,
    const char* name,
    napi_callback callback) {
  napi_value function;
  Check(env, napi_create_function(
      env, name, NAPI_AUTO_LENGTH, callback, nullptr, &function));
  Check(env, napi_set_named_property(env, object, name, function));
}

Napi::Value SetStorageItem(const Napi::CallbackInfo& info) {
  Napi::Env env = info.Env();
  // Method:
  //   setStorageItem(
  //     key: string,
  //     value: string,
  //   ): void
  // types/napi-native-module.d.ts
  if (info.Length() < 2) {
    return env.Undefined();
  }
  Napi::String key = info[0].As<Napi::String>();
  Napi::String value = info[1].As<Napi::String>();
  g_storage[key.Utf8Value()] = value.Utf8Value();
  return env.Undefined();
}

Napi::Value GetStorageItem(const Napi::CallbackInfo& info) {
  Napi::Env env = info.Env();
  // Method:
  //   getStorageItem(
  //     key: string,
  //     callback: function,
  //   ): void
  // types/napi-native-module.d.ts
  if (info.Length() < 2) {
    return env.Undefined();
  }
  Napi::String key = info[0].As<Napi::String>();
  Napi::Function callback = info[1].As<Napi::Function>();
  auto iter = g_storage.find(key.Utf8Value());
  std::string value = iter == g_storage.end() ? "" : iter->second;
  callback.Call({Napi::String::New(env, value)});
  return env.Undefined();
}

Napi::Value ClearStorage(const Napi::CallbackInfo& info) {
  Napi::Env env = info.Env();
  // Method:
  //   clearStorage(): void
  // types/napi-native-module.d.ts
  g_storage.clear();
  return env.Undefined();
}

napi_value SetStorageItemCallback(napi_env env, napi_callback_info info) {
  return SetStorageItem(Napi::CallbackInfo(env, info));
}

napi_value GetStorageItemCallback(napi_env env, napi_callback_info info) {
  return GetStorageItem(Napi::CallbackInfo(env, info));
}

napi_value ClearStorageCallback(napi_env env, napi_callback_info info) {
  return ClearStorage(Napi::CallbackInfo(env, info));
}

void BindNativeLocalStorageModule(napi_env env, napi_value exports) {
  SetFunction(env, exports, "setStorageItem", SetStorageItemCallback);
  SetFunction(env, exports, "getStorageItem", GetStorageItemCallback);
  SetFunction(env, exports, "clearStorage", ClearStorageCallback);
}

static napi_value CreateNativeLocalStorageModule(
    ::lynx::registration::LynxNapiEnv env,
    ::lynx::registration::LynxNapiValue exports,
    const char* module_name,
    void* opaque) {
  (void)module_name;
  (void)opaque;
  BindNativeLocalStorageModule(env, exports);
  return exports;
}

}  // namespace

LYNX_REGISTER_NATIVE_MODULE(
    "NativeLocalStorageModule",
    CreateNativeLocalStorageModule,
    nullptr)

#ifdef USE_WEAK_SUFFIX_NAPI
#include "weak_napi_undefs.h"
#endif
```

After the native code is ready, compile it into the host app or into a desktop
native library that the host can load. See [Native Libraries and
Autolink](/next/guide/autolink.md?platform=lynxtron) for how to distribute the library
and wire it into a Lynxtron host. Once the library is loaded, the static
registration exposes `NativeLocalStorageModule` through `NativeModules`, so a
Lynx page can call it directly:

```ts title="src/App.tsx"
NativeModules.NativeLocalStorageModule.setStorageItem('language', 'JavaScript');
NativeModules.NativeLocalStorageModule.getStorageItem('language', (value) => {
  console.log(value); // 'JavaScript'
});
```

If the same desktop native library also exposes a custom Element, see the
[Desktop platform section of Custom Element](/next/guide/custom-native-component.md?platform=desktops).

Congratulations! You have successfully created a native module. If you want to create a native module in your application, you first need to integrate Lynx by referring to the [Integrate with Existing Apps](/next/guide/start/integrate-with-existing-apps.md) guide, and then follow the steps above to create the native module.

## Type Mapping Table

| TypeScript    | iOS(Objective-C)                                  | Android(Java)                                     | HarmonyOS(ets) | Weak Node-API                     |
| ------------- | ------------------------------------------------- | ------------------------------------------------- | -------------- | --------------------------------- |
| `null`        | `nil`                                             | `null`                                            | `null`         | `Napi::Value` / `env.Null()`      |
| `undefined`   | `nil`                                             | `null`                                            | `undefined`    | `Napi::Value` / `env.Undefined()` |
| `boolean`     | `BOOL` (or `NSNumber` when used inside objects)   | `boolean` (or `Boolean` when used inside objects) | `boolean`      | `Napi::Boolean`                   |
| `number`      | `double` (or `NSNumber` when used inside objects) | `double` (or `Number` when used inside objects)   | `number`       | `Napi::Number`                    |
| `string`      | `NSString`                                        | `String`                                          | `string`       | `Napi::String`                    |
| `BigInt`      | `NSString`                                        | `long` (or `Number` when used inside objects)     | `BigInt`       | `Napi::BigInt`                    |
| `ArrayBuffer` | `NSData`                                          | `byte[]`                                          | `Buffer`       | `Napi::ArrayBuffer`               |
| `object`      | `NSDictionary`                                    | `com.lynx.react.bridge.ReadableMap`               | `object`       | `Napi::Object`                    |
| `array`       | `NSArray`                                         | `com.lynx.react.bridge.ReadableArray`             | `array`        | `Napi::Array`                     |
| `function`    | block `void (^)(id)`                              | `com.lynx.react.bridge.Callback`                  | `function`     | `Napi::Function`                  |

## Native Module Permission Verification (Experimental)

Starting from Lynx SDK 3.5, developers can use `LynxViewBuilder` to set a native module validator for the current `LynxView`, thereby controlling all native module calls within the `LynxView`. Currently, this feature is only supported on Android and iOS, with HarmonyOS support to be added in the future.

iOSAndroidWhen creating a `LynxView` using `LynxViewBuilder`, register a native module validator through the `registerModuleAuthValidator` interface. The validator will apply to all native module calls within the current `LynxView`.
**Native Module Validator Interface**
```java title=""

/**
* LynxMethod verification interface, used to verify whether the LynxMethod is allowed to be
* called
*/
public interface AuthValidator {
/**
 *
 * @param moduleName The name of the called native module
 * @param methodName The name of the called native module method
 * @param methodParams The parameters of the called native module method
 * @return
 * true: Verification passed, the native module call will be executed
 * false: Verification failed, the native module call will not be executed, and a JS error will be generated
 */
boolean verify(String moduleName, String methodName, JavaOnlyArray methodParams);
}

```
**Native Module Validator Registration Method**
```java title=""

LynxViewBuilder builder = LynxView.builder()
// Register the validator instance with LynxViewBuilder
.registerModuleAuthValidator(new LynxModule.AuthValidator() {
void validate(@NonNull String moduleName, @NonNull String moduleName, @NonNull ReadableMap params) {
//Validation logic
return result;
}
}
LynxView view = builder.build(context);

```
When creating a `LynxView` using `LynxViewBuilder`, register a native module validator through the `registerMethodAuth` interface. The validator will apply to all native module calls within the current `LynxView`.
**Native Module Validator Interface**
```objective-c title=""

/**
*
* @param method: The name of the called native module method
* @param module: The called native module
* @param invoke_session: The timestamp of the native module call
* @param inv：The dynamic invocation method for this call
* @return
* true: Verification passed, the native module call will be executed
* false: Verification failed, the native module call will not be executed, and a JS error will be generated
*/
typedef BOOL (^LynxMethodBlock)(NSString *method, NSString *module, NSString *invoke_session,
NSInvocation *inv);

```
**Native Module Validator Registration Method**
```objective-c title=""

// Register the validator instance with LynxViewBuilder
LynxViewBuilder *builder = GetLynxViewBuilder();
[builder.config registerMethodAuth:validtorBlock];

```
